import json
R = []
def add(p, r): R.append([p, r])
def name(i): return "abcdefgh"[i % 8] + str(8 - i // 8)
def rc(i): return divmod(i, 8)

def pat(spec, repl=None):
    """spec: pos->regex class; repl: pos->new char. Returns (regex, replacement) over 64-char board."""
    repl = repl or {}
    keys = sorted(set(spec) | set(repl))
    rx, rp, g, prev = "", "", 0, 0
    for k in keys:
        if k > prev:
            g += 1; rx += "(.{%d})" % (k - prev); rp += "\\g<%d>" % g
        cls = spec.get(k, ".")
        if k in repl:
            rx += cls; rp += repl[k]
        else:
            g += 1; rx += "(" + cls + ")"; rp += "\\g<%d>" % g
        prev = k + 1
    if prev < 64:
        g += 1; rx += "(.{%d})" % (64 - prev); rp += "\\g<%d>" % g
    return rx, rp, g

def plain(spec):
    rx, prev = "", 0
    for k in sorted(spec):
        if k > prev: rx += ".{%d}" % (k - prev)
        rx += spec[k]; prev = k + 1
    return rx

E = r"\."
W = "[PNBRQK]"
NW = "[^PNBRQK]"
B = "[pnbrqk]"

# normalize
add(r"^(\S+) w (\S+) (\S+).*$", r"\1 \2 \3")
add("/", "")
for d in range(8, 0, -1):
    add(str(d) + r"(?=\S* )", "." * d)
add(r"^(.+)$", "\n".join("#%s:\\1" % name(i) for i in range(64)))
for f in range(64):
    add("#%s:(?=.{%d}%s).*\\n?" % (name(f), f, NW), "")

def between(f, t):
    r1, c1 = rc(f); r2, c2 = rc(t)
    dr = (r2 > r1) - (r2 < r1); dc = (c2 > c1) - (c2 < c1)
    out = []; r, c = r1 + dr, c1 + dc
    while (r, c) != (r2, c2):
        out.append(r * 8 + c); r += dr; c += dc
    return out

moves = {}  # f -> list of (t, piece, extra)
for f in range(64):
    r1, c1 = rc(f)
    lst = moves.setdefault(f, [])
    for t in range(64):
        if t == f: continue
        r2, c2 = rc(t); dr, dc = r2 - r1, c2 - c1
        ortho = dr == 0 or dc == 0
        diag = abs(dr) == abs(dc)
        if ortho or diag:
            lst.append((t, "Q"))
            lst.append((t, "R" if ortho else "B"))
            if max(abs(dr), abs(dc)) == 1: lst.append((t, "K"))
        if sorted([abs(dr), abs(dc)]) == [1, 2]: lst.append((t, "N"))
        if dr == -1 and abs(dc) <= 1: lst.append((t, "P"))
        if dr == -2 and dc == 0 and r1 == 6: lst.append((t, "P2"))
    if f == 60:
        lst.append((62, "OO")); lst.append((58, "OOO"))

targets = {f: sorted(set(t for t, _ in moves[f]), key=lambda x: x) for f in moves}
for f in range(64):
    add("#%s:(.*)" % name(f), "\n".join("#%s%s:\\1" % (name(f), name(t)) for t in targets[f]))

REST = r" ([KQkq-]+) (\S+)"
for f in range(64):
    for t, p in moves[f]:
        tag = "#%s%s:" % (name(f), name(t))
        if p in "QRBNK":
            spec = {f: p, t: NW}
            for b in (between(f, t) if p in "QRB" else []): spec[b] = E
            rx, rp, g = pat(spec, {f: ".", t: p})
            add(tag + rx + REST, "!:" + rp + " \\g<%d> -" % (g + 1))
        elif p == "P":
            np = "Q" if t < 8 else "P"
            if t % 8 == f % 8:
                rx, rp, g = pat({f: "P", t: E}, {f: ".", t: np})
                add(tag + rx + REST, "!:" + rp + " \\g<%d> -" % (g + 1))
            else:
                rx, rp, g = pat({f: "P", t: B}, {f: ".", t: np})
                add(tag + rx + REST, "!:" + rp + " \\g<%d> -" % (g + 1))
                if 16 <= t < 24:  # en passant
                    rx, rp, g = pat({f: "P", t: E, t + 8: "p"}, {f: ".", t: "P", t + 8: "."})
                    add(tag + rx + r" ([KQkq-]+) " + name(t), "!:" + rp + " \\g<%d> -" % (g + 1))
        elif p == "P2":
            rx, rp, g = pat({f: "P", f - 8: E, t: E}, {f: ".", t: "P"})
            add(tag + rx + REST, "!:" + rp + " \\g<%d> %s" % (g + 1, name(f - 8)))
        elif p == "OO":
            rx, rp, g = pat({60: "K", 61: E, 62: E, 63: "R"}, {61: "K", 62: "K"})
            add(tag + rx + r" ([Qkq-]*K[Qkq-]*) (\S+)", "!K:" + rp + " \\g<%d> -" % (g + 1))
        elif p == "OOO":
            rx, rp, g = pat({56: "R", 57: E, 58: E, 59: E, 60: "K"}, {58: "K", 59: "K"})
            add(tag + rx + r" ([Kkq-]*Q[Kkq-]*) (\S+)", "!Q:" + rp + " \\g<%d> -" % (g + 1))
add(r"(?m)^#.*\n?", "")

# check detection
for k in range(64):
    r, c = rc(k); alts = []
    for dr, dc in [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]:
        if 0 <= r+dr < 8 and 0 <= c+dc < 8: alts.append(plain({(r+dr)*8+c+dc: "n"}))
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if (dr or dc) and 0 <= r+dr < 8 and 0 <= c+dc < 8:
                alts.append(plain({(r+dr)*8+c+dc: "k"}))
    for dc in (-1, 1):
        if r > 0 and 0 <= c+dc < 8: alts.append(plain({(r-1)*8+c+dc: "p"}))
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if not (dr or dc): continue
            cls = "[rq]" if dr == 0 or dc == 0 else "[bq]"
            rr, cc, path = r+dr, c+dc, []
            while 0 <= rr < 8 and 0 <= cc < 8:
                j = rr*8+cc
                if len(path) > 0:
                    sp = {p: E for p in path}; sp[j] = cls
                    alts.append(plain(sp))
                path.append(j); rr += dr; cc += dc
    add(r"(?m)^!\w?:(?=.{%d}K)(?=%s).*\n?" % (k, "|".join(alts)), "")
# restore castling
add(r"(?m)^!K:(.{60})KKKR", r"!:\1..RK")
add(r"(?m)^!Q:(.{56})R.KKK", r"!:\1..KR.")
# rights
for letter, sq in [("K", [(60, "K"), (63, "R")]), ("Q", [(60, "K"), (56, "R")]),
                   ("k", [(4, "k"), (7, "r")]), ("q", [(4, "k"), (0, "r")])]:
    for s, pc in sq:
        add(r"(?m)^(!:(?!.{%d}%s).{64} [KQkq]*)%s" % (s, pc, letter), r"\1")
add(r"(?m)^(!:.{64})  ", r"\1 - ")
add(r"(?m)^!:" + "(.{8})" * 8 + " ", "/".join("\\%d" % i for i in range(1, 9)).join(["", " b "]))
for d in range(8, 0, -1):
    add(r"\.{%d}" % d, str(d))
add(r"(?m) (\S+)$", r" \1 0 0")
add(r"\n+$", "")
json.dump(R, open("/app/re.json", "w"))
print(len(R))
